/// [key] metnini dilde verir; {n} yerine [n] yazılır.
String okt(String lang, String key, [String n = '']) {
  final l = kOkeyTexts[key];
  if (l == null) return key;
  return Strings.pick(l, lang).replaceAll('{n}', n);
}
